class RotateHandler
  def initialize(log, &on_rotate)
    @log = log
    @inode = nil
    @fsize = -1  # first
    @on_rotate = on_rotate
  end

  def on_notify(stat)
    if stat.nil?
      inode = nil
      fsize = 0
    else
      inode = stat.ino
      fsize = stat.size
    end

    if @inode != inode || fsize < @fsize
      @on_rotate.call(stat)
    end
    @inode = inode
    @fsize = fsize
  rescue
    @log.error $!.to_s
    @log.error_backtrace
  end
end

